/* --- 2. 基础与段落样式 (遵嘱，P标签保持不变) --- */
* {
    box-sizing: border-box;
}
p:not(.MuiTypography-root):not(.MuiTypography-body2) {
    font-family: "Microsoft YaHei", "Arial", sans-serif;
    font-size: 16px;
    line-height: 24px;
    margin-top: 20px;
    margin-bottom: 16px;
    margin-left: 17px;
    margin-right: 13px;
    letter-spacing: 0.5px;
}
/* --- 3. [升级] H1 标题样式 --- */
h1 {
    font-family: "Microsoft YaHei", "Arial", sans-serif;
    font-size: 1.2em; /* 使用em单位更灵活 */
    font-weight: bold;
    background-color: #f0f0f0; /* 柔和的背景灰 */
    color: #333;
    padding: 10px 15px; /* 增加内边距 */
    margin-top: 2em; /* 与上方内容保持距离 */
    margin-bottom: 1em;
    border-bottom: 2px solid #e0e0e0; /* 用底部线条分割 */
    border-left: 5px solid #666; /* 左侧添加强调色条 */
    border-radius: 4px; /* 轻微的圆角 */
}

/* --- 4. [升级] Details & Summary 信息面板 --- */
details {
    background: #f9f9f9; /* 更轻盈的背景色 */
    border: 1px solid #eee; /* 细边框代替粗边框 */
    border-left: 4px solid #aaa; /* 左侧强调线使用柔和的灰色 */
    border-radius: 6px; /* 更明显的圆角 */
    padding: 0.5em 1em; /* 调整内边距 */
    margin: 1em 0;
    transition: all 0.2s ease-in-out; /* 为悬浮和展开添加过渡动画 */
}
details:hover {
    border-left-color: #333; /* 鼠标悬浮时，左侧强调线变深 */
}
summary {
    color: #333; /* 更柔和的字体颜色 */
    font-size: 1.2em;
    font-weight: bold;
    cursor: pointer;
    padding: 0.5em 0;
    outline: none; /* 去掉点击时的虚线框 */
    position: relative; /* 为小三角图标定位 */
    transition: margin 0.2s ease-in-out; /* 为展开时的边距变化添加动画 */
}
/* 使用::before伪元素创建小三角图标 */
summary::before {
    content: '▸';
    position: absolute;
    left: -0.8em;
    top: 0.6em;
    transition: transform 0.2s ease-in-out; /* 为旋转添加动画 */
}
details[open] > summary {
    margin-bottom: 1em;
    border-bottom: 1px solid #eee; /* 展开后的分割线更细 */
}
/* 当details展开时，旋转小三角图标 */
details[open] > summary::before {
    transform: rotate(90deg);
}
/* --- 4.5. [整序] 卷轴样式 · 情报整理 --- */
details table {
    width: 100%;
    border-collapse: collapse; /* 合并边框，使表格更整洁 */
    margin-top: 1em;
}

/* 针对表头和单元格的通用样式 */
details th,
details td {
    border: 1px solid #e0e0e0; /* 使用与主题匹配的浅灰色边框 */
    padding: 10px 12px;
    text-align: left;
    color: #333; /* 确保字体颜色与你的主题一致 */
    background-color: transparent !important; /* 核心封印术：强制背景透明，破除所有默认背景色！*/
}

/* 美化表头，使其更易区分 */
details th {
    background-color: #f0f0f0; /* 给表头一个略深的背景，与H1标题背景色呼应 */
    font-weight: bold;
}

/* 为数据行添加一个悬停反馈，提升交互体验 */
details tbody tr:hover {
    background-color: #f5f5f5; /* 鼠标悬停时，行背景变为柔和的灰色高亮 */
}


/* --- 6. 其他保留样式 --- */
font {
    font-family: "Microsoft YaHei", "Arial", sans-serif;
    font-weight: bold;
}

p[Foreword] {
    font-family: "Microsoft YaHei", "Arial", sans-serif;
    font-style: italic;
    text-decoration: underline;
    color: #333;
}
/* --- 新增：美化Details内部的PRE内容 --- */

pre {
    font-family: "Microsoft YaHei", "Arial", sans-serif;
    font-size: 1em; /* 继承父级字体大小 */
    line-height: 1.7; /* 设置合适的行高 */
    color: #363636; /* 设置统一的字体颜色 */
    background-color: transparent; /* 确保背景是透明的 */
    border: none; /* 去掉可能的边框 */
    padding: 0; /* 去掉内边距 */
    margin: 0; /* 去掉外边距 */
    white-space: pre-wrap !important; /* 保留自动换行，并提升优先级以防被意外覆盖 */
}

/* --- 6. 命运选择面板 (Destiny Choice Panel) · 亮色主题 [最终修正 v3] --- */
